var a = new Thread(() =>
{
    for (int i = 0; i < 3; i++)
        Console.WriteLine($"A{i}");
});
var b = new Thread(() =>
{
    for (int i = 0; i < 3; i++)
        Console.WriteLine($"B{i}");
});
a.Start();
b.Start();
a.Join();
b.Join();
Console.WriteLine("Fertig");

int erg = 0;
var t = new Thread(() =>
{
    Thread.Sleep(100); // 100 ms
    erg = 42;
});
t.Start();
Console.WriteLine(erg); // meist 0
t.Join();
Console.WriteLine(erg); // 42

Task<int> task =
    Task.Run(() => 6 * 7);
Console.WriteLine(task.Result); // 42

var tasks = new[]
{
    Task.Run(() => 1),
    Task.Run(() => 2)
};
Task.WaitAll(tasks);
Console.WriteLine(
    tasks.Sum(x => x.Result)); // 3

